mapper.select:

       SELECT #{push} AS time,entrance_id AS area,service AS type,SUM(sum) AS count
       FROM ntc_entrance_report
       WHERE report_time >= #{start}
          AND report_time < #{end}
          AND (
              service BETWEEN 16 AND 40
		      OR service BETWEEN 258 AND 273
		      OR service = 576
		      )
	   GROUP BY type,area
	   ORDER BY count DESC
	   LIMIT 20;


SELECT #{push} AS time,url AS type,SUM(sum) AS count
FROM ntc_reject_url_statistic
WHERE stat_time >= #{start}
    AND stat_time < #{end}
GROUP BY type
ORDER BY count DESC
LIMIT 100;


SELECT #{push} AS time,url AS type,ip_addr AS ip,SUM(sum) AS count
FROM ntc_reject_url_statistic
WHERE stat_time >= #{start}
    AND stat_time < #{end}
GROUP BY type,ip
ORDER BY count desc
LIMIT 100;


SELECT #{push} time ,website type ,SUM(sum) count
FROM ntc_reject_website_statistic
  WHERE stat_time >= #{start}
  AND stat_time < #{end}
GROUP BY type
ORDER BY count DESC
LIMIT 100;


SELECT #{push} time,website type,ip_addr ip,SUM(sum) count
FROM ntc_reject_website_statistic
WHERE stat_time >= #{start}
    AND stat_time < #{end}
GROUP BY type ,ip
ORDER BY count DESC
LIMIT 100;


